import torch
import torch.nn as nn

class DynamicMLP(nn.Module):
  def __init__(self, sizes):
    super().__init__()
    # Correct parameter registration for list of modules
    self.layers = nn.ModuleList(
        [nn.Linear(sizes[i], sizes[i + 1]) for i in range(len(sizes) - 1)]
    )

  def forward(self, x):
    for layer in self.layers:
      x = torch.relu(layer(x))
    return x

model = DynamicMLP([64, 128, 256, 10])
x = torch.randn(8, 64)
print(model(x).shape)  # torch.Size([8, 10])

import torch
import torch.nn as nn

class MultiHeadBranch(nn.Module):
  def __init__(self):
    super().__init__()
    self.heads = nn.ModuleDict({
        'vision': nn.Linear(512, 10),
        'text': nn.Linear(768, 10),
    })

  def forward(self, x, head_name):
    return self.heads[head_name](x)

model = MultiHeadBranch()
x_text = torch.randn(4, 768)
output = model(x_text, head_name='text')

print(output.shape)  # torch.Size([4, 10])

import torch
import torch.nn as nn

class CustomWeights(nn.Module):
  def __init__(self, num_params, dim):
    super().__init__()
    # Register list of standalone raw weight tensors
    self.params = nn.ParameterList(
        [nn.Parameter(torch.randn(dim, dim)) for _ in range(num_params)]
    )

  def forward(self, x):
    for p in self.params:
      x = torch.matmul(x, p)
    return x

model = CustomWeights(num_params=3, dim=16)
x = torch.randn(4, 16)
print(model(x).shape)  # torch.Size([4, 16])
